CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email citext NOT NULL UNIQUE,username citext NOT NULL UNIQUE,auth_subject text NOT NULL UNIQUE,email_verified_at timestamptz,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','deleted')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,CONSTRAINT username_format CHECK(username::text ~ '^[a-zA-Z0-9_]{3,24}$'));
CREATE TABLE IF NOT EXISTS profiles (user_id uuid PRIMARY KEY REFERENCES users(id),display_name text,avatar_asset_id uuid,privacy_settings jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS marketing_consents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),channel text NOT NULL CHECK(channel IN ('email','push')),purpose text NOT NULL,brand_scope text NOT NULL,opted_in boolean NOT NULL DEFAULT false,notice_version text NOT NULL,source text NOT NULL,ip_hash text,recorded_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS marketing_consents_lookup ON marketing_consents(user_id,purpose,channel,recorded_at DESC);
CREATE TABLE IF NOT EXISTS email_suppressions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),channel text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),push_token_encrypted text,platform text NOT NULL CHECK(platform IN ('ios','android','web')),last_seen_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
